import sdk, { HttpRequest, HttpResponse } from "@scrypted/sdk";
import AdvancedNotifierPlugin from "./main";
import fs from 'fs';

export const serveGif = async (props: {
    gifPath: string,
    request: HttpRequest,
    response: HttpResponse,
    plugin: AdvancedNotifierPlugin,
    corsHeaders?: Record<string, string>,
}) => {
    const { gifPath, response, plugin, corsHeaders = {} } = props;

    const logger = plugin.getLogger();

    logger.info(JSON.stringify({ gifPath }));

    const gifBuf = await fs.promises.readFile(gifPath);

    response.send(gifBuf, {
        headers: {
            'Content-Type': 'image/gif',
            ...corsHeaders,
        }
    });
    return;
}

